<script setup lang="ts">
import { ref, onMounted } from 'vue';
const props = defineProps<{ api: (path: string, method?: string, body?: unknown) => Promise<any> }>();
const value = ref<any>(), message = ref(''), busy = ref(false);
const mib = (n: number) => (n / 1024 / 1024).toFixed(1);
async function refresh() { try { value.value = await props.api('admin/operations'); } catch (e) { message.value = (e as Error).message; } }
async function cleanup() { busy.value = true; try { const r = await props.api('admin/operations/cleanup', 'POST', {}); message.value = `已清理 ${r.expiredSessions} 个过期会话、${r.expiredPreviews} 个过期预览。没有删除任务、审核包或公开历史。`; await refresh(); } catch (e) { message.value = (e as Error).message; } finally { busy.value = false; } }
onMounted(refresh);
</script>
<template><section class="panel operations-panel"><div class="section-heading"><h2>存储与运行状态</h2><button class="text-button" @click="refresh">刷新状态</button></div><template v-if="value"><div class="operation-grid"><div><span>应用 RSS / 进程峰值</span><strong>{{ mib(value.runtime.rssBytes) }} / {{ mib(value.runtime.processPeakRssBytes) }} MiB</strong></div><div><span>整机可用 / 总内存</span><strong>{{ mib(value.runtime.freeMemoryBytes) }} / {{ mib(value.runtime.totalMemoryBytes) }} MiB</strong></div><div><span>SQLite 已分配 / 上限</span><strong>{{ mib(value.storage.databaseAllocatedBytes) }} / {{ mib(value.storage.limits.maxDatabaseBytes) }} MiB</strong></div><div><span>审核包内容 / 上限</span><strong>{{ mib(value.storage.artifactBytes) }} / {{ mib(value.storage.limits.maxArtifactTotalBytes) }} MiB</strong></div></div><p class="muted">候选 {{value.storage.discovery.candidates}} / 5000 · 发现轮次 {{value.storage.discovery.runs}} / 1000 · 统一队列 {{value.storage.discovery.queued}} / 10 · 模型测试 {{value.storage.modelTests}} / {{value.storage.modelTestLimit}} · 任务 {{ value.storage.tasks }} / {{ value.storage.limits.maxTasks }} · 发布历史 {{ value.storage.publications }} / {{ value.storage.limits.maxPublications }} · {{ value.runtime.platform }} / {{ value.runtime.cpuCount }} 个可用逻辑处理器</p><p class="config-tip">达到存储上限时会暂停接收新工作，并保留已有记录。可定期备份数据，或调整服务端存储上限。</p><button :disabled="busy" @click="cleanup">清理过期会话与发布预览</button></template><p v-if="message" role="status">{{ message }}</p></section></template>
